#!/usr/bin/env python3
"""Patrick, Tue Oct 13: one-route map-led scroll story. python3 build.py -> index.html (CSS in style.css)"""
import json
gm=lambda q:'https://www.google.com/maps/search/?api=1&query='+q.replace(' ','+')
A=lambda u,t:f'<a href="{u}" target="_blank" rel="noopener">{t}</a>'
def links(*ls): return '<ul class="links">'+''.join('<li>'+A(u,t)+'</li>' for t,u in ls)+'</ul>'
def pts(*ps): return '<ul class="pts">'+''.join(f'<li><b>{a}</b><span>{b}</span></li>' for a,b in ps)+'</ul>'
def nums(*ns): return '<dl class="nums">'+''.join(f'<div><dt>{a}</dt><dd class="n">{b}</dd><dd class="s">{c}</dd></div>' for a,b,c in ns)+'</dl>'
def ph(src,alt): return f'<div class="ph"><img src="{src}" alt="{alt}"></div>'
TH='https://thumb.wikimedia.org/wikipedia/commons/thumb/'
IMG=dict(
 kyudo=TH+'2/29/Professor_Inagaki_Genshiro.jpg/960px-Professor_Inagaki_Genshiro.jpg',
 animate='https://upload.wikimedia.org/wikipedia/commons/c/c5/ANIMATE-Ikebukuro.JPG',
 ramen=TH+'8/8c/Very_hot_tsukemen_%28close-up%29.jpg/960px-Very_hot_tsukemen_%28close-up%29.jpg',
 poke=TH+'e/ec/Mega_Tokyo_Pok%C3%A9mon_Center_1.jpg/960px-Mega_Tokyo_Pok%C3%A9mon_Center_1.jpg')
# lat, lon, full name, short label, label side, time, rail-less title
P=[None,
 (35.6882,139.7735,'Hotel lobby, Nihonbashi','Hotel','r','9:30'),
 (35.7019,139.7678,'Kanda Myojin shrine','Myojin','r','9:50'),
 (35.6949,139.7690,'Koyama Kyugu, Kanda','Koyama','r','10:15'),
 (35.7303,139.7152,'Animate Ikebukuro','Animate','r','11:30'),
 (35.7308,139.7132,'Kikanbo Ikebukuro','Kikanbo','t','12:15'),
 (35.7289,139.7192,'Pokémon Center Mega Tokyo','Pokémon Center','r','13:15'),
 (35.7262,139.7135,'Disk Union Ikebukuro (if it fits)','Disk Union','l','14:15')]
TT=[('9:30','Meet at the hotel lobby (to be confirmed)'),('9:35','Ginza Line to Suehirocho, then walk to the shrine'),('9:50','Kanda Myojin shrine'),('10:05','Walk to the bow shop'),('10:15','Koyama Kyugu, Kanda main store'),('11:00','Marunouchi Line from Awajicho to Ikebukuro'),('11:30','Animate Ikebukuro main store'),('12:15','Lunch at Kikanbo'),('13:15','Pokémon Center Mega Tokyo'),('14:15','Disk Union Ikebukuro, if it fits'),('14:30','Done, in Ikebukuro')]
tt=''.join(f'<tr class="st-plain"><td class="v">{t}</td><td><span class="k">{k}</span></td></tr>' for t,k in TT)
def step(i,h,body):
    t=P[i][5]
    return f'<article class="step" data-i="{i}"><p class="no"><i>{i}</i>{t}</p><h2>{h}</h2>{body}</article>'
S=[]
S.append(f'<article class="step" data-i="0"><p class="no"><i>0</i>The whole day</p><h2>One route,<span class="l2">9:30 to <em>14:30</em></span></h2><p class="lead">Two old Kanda stops in the morning, then Ikebukuro for anime, ramen, Pokémon and, if it fits, metal records. Two train rides, no changes, and the rest on foot.</p><div class="tt"><p class="cap">The day</p><table>{tt}</table></div>'
 +pts(('Good for','Bows, anime and manga, heavy metal records, with one proper ramen lunch in the middle.'),('Keep in mind','Kikanbo is spicy, but you can ask for it milder. Times are approximate.'))
 +links(('Open the whole route in Google Maps','https://www.google.com/maps/dir/?api=1&origin=Mitsui+Garden+Hotel+Nihonbashi+Premier&destination=Disk+Union+Ikebukuro&waypoints=Kanda+Myojin%7CKoyama+Kyugu+Kanda%7CAnimate+Ikebukuro+Main+Store%7CKikanbo+Ikebukuro%7CPokemon+Center+Mega+Tokyo+Sunshine+City&travelmode=transit'))+'</article>')
S.append(step(1,'We meet in <em>the lobby</em>','<p class="lead">I come to the lobby of the Mitsui Garden Hotel Nihonbashi Premier. Mitsukoshimae station is right next to the hotel.</p>'+nums(('Time','9:30','Tuesday, October 13'),('Finish','14:30','Ikebukuro'))+'<p class="note" style="font-size:13px;color:var(--mute)">Meeting time 9:30, still being confirmed with Tree.</p>'+links(('Hotel on Google Maps',gm('Mitsui Garden Hotel Nihonbashi Premier')))))
S.append(step(2,'The <em>shrine</em>','<p class="lead">Kanda Myojin is an old Edo shrine above Akihabara, and a favourite of anime fans. We take the Ginza Line from Mitsukoshimae to Suehirocho (about 5 minutes), then walk 10 minutes. The grounds are open early and quiet before the shops open.</p>'+links(('Kanda Myojin on Google Maps',gm('Kanda Myojin')),('Official site','https://www.kandamyoujin.or.jp/'))))
S.append(step(3,'The <em>bow maker</em>',ph(IMG['kyudo'],'An archer in hakama at full draw')+'<p class="lead">Koyama Kyugu has made bows for over 200 years and has its own workshop for bows, arrows and gloves. It opened at 10:00, so we arrive to a calm shop. You can hold the bows and ask the staff anything. This is the main stop, so we take our time. It is a 15 minute walk from the shrine.</p>'
 +'<div class="cafes"><div class="cf"><div class="cb"><b>Koyama Kyugu, Kanda main store</b><p class="rt"><span class="st">★ 4.2</span> · 217 Google reviews</p><p>Open Tuesday 10:00 to 19:00.</p><small>Rating from Google Maps, October 2026.</small></div></div></div>'
 +links(('Koyama Kyugu on Google Maps',gm('Koyama Kyugu Kanda')),('Official site','https://koyama-kyugu.co.jp/store/'))))
S.append(step(4,'<em>Animate</em>,<span class="l2">Japan\'s biggest anime shop</span>',ph(IMG['animate'],'The Animate Ikebukuro main store building')+'<p class="lead">From Awajicho station (one minute from the bow shop) it is the Marunouchi Line to Ikebukuro, about 17 minutes with no changes. Animate\'s main store is about 5 minutes on foot from the east exit: manga, character goods, and anime shops on the streets around it.</p>'+nums(('Open','10:00 to 21:00','Tuesday'))+links(('Animate on Google Maps',gm('Animate Ikebukuro Main Store')),('Official site','https://www.animate.co.jp/shop/ikebukuro/'))))
S.append(step(5,'<em>Spicy ramen</em>,<span class="l2">at Kikanbo</span>',ph(IMG['ramen'],'A bowl of spicy ramen')+'<p class="lead">Red miso broth with chili and Sichuan pepper. You choose how hot and how numbing, and you can ask for it milder. It is a few minutes on foot from Animate. There can be a short line at lunchtime.</p>'+nums(('Open','11:00 to 21:30','Tuesday'))+links(('Kikanbo on Google Maps',gm('Kikanbo Ikebukuro')),('Official site','https://kikanbo.co.jp/pages/shop'))))
S.append(step(6,'<em>Pokémon Center</em>,<span class="l2">Sunshine City</span>',ph(IMG['poke'],'Inside the Pokémon Center Mega Tokyo')+'<p class="lead">We walk to Sunshine City, about 15 minutes. The Pokémon Center Mega Tokyo is on the second floor of the Alpa shopping area, the biggest Pokémon store in Tokyo. We have about an hour here.</p>'+nums(('Open','10:00 to 20:00','Tuesday'))+links(('Pokémon Center on Google Maps',gm('Pokemon Center Mega Tokyo Sunshine City')),('Official site','https://shop.pokemon.co.jp/ja/shop/pokemoncenter-megatokyo/'))))
S.append(step(7,'<em>Metal</em> records,<span class="l2">and done</span>',''.join(['<p class="lead">Disk Union has rock and metal records and band T-shirts, new and used. It is about 15 minutes on foot back from Sunshine City, so we only go if we still have time and energy. If not, we finish at the Pokémon Center. Either way we are done around 14:30 in Ikebukuro. Back to Nihonbashi is about 30 minutes: Marunouchi Line to Otemachi, then one stop on the Hanzomon Line. Or we split here.</p>',nums(('Open','12:00 to 20:00','Tuesday')),links(('Disk Union on Google Maps',gm('Disk Union Ikebukuro')),('Official site','https://diskunion.net/shop/ikebukuro'))])))
night='<section class="x"><p class="note" style="font-size:13px;color:var(--mute);margin-top:0"><b style="color:var(--ink)">If you want a bit more tonight:</b> two rock bars in Ikebukuro, both open on Tuesdays. '+A(gm('Rock Bar Castle gate Ikebukuro'),'Castle Gate')+' 19:00 to 24:00 (closed Sun and Mon), '+A(gm('LANDSROCK Ikebukuro'),'LANDSROCK')+' 19:00 to 5:00 (closed Sun). Hours from '+A('https://peraichi.com/landing_pages/view/castlegate','Castle Gate')+' and '+A('https://lands-rock.com/','LANDSROCK')+'.</p></section>'
credit='<footer class="credit"><p class="note" style="margin:0 0 10px">Times are approximate and can move on the day. Message Yuuki if you want to change anything.</p><details><summary>Photo credits</summary><ul><li>Professor Inagaki Genshiro.jpg CC BY-SA 3.0</li><li>ANIMATE-Ikebukuro.JPG by Itasan, CC BY-SA 3.0</li><li>Very hot tsukemen (close-up).jpg CC BY 2.0</li><li>Mega Tokyo Pokémon Center 1.jpg by Maplestrip, CC BY 3.0</li></ul><p>Photos via Wikimedia Commons. Map: Tiles © Esri / © '+A('https://www.openstreetmap.org/copyright','OpenStreetMap')+'</p></details></footer>'
dn=''.join(f'<button type="button" class="dn" data-i="{i}" aria-label="{"The whole day" if i==0 else P[i][5]}">{i}</button>' for i in range(8))
head='<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light"><meta name="robots" content="noindex,nofollow"><title>Your day in Tokyo</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Inter:wght@500;700;900&display=swap"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.css"><script src="https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.js"></script><style>'+open('style.css').read()+'</style></head><body>'
intro='<div class="wrap"><div class="mapbox"><div id="map" aria-label="Map of the day"></div><p class="where"><small>Tue, October 13</small><b>The whole day</b></p><nav class="dial" aria-label="Switch stop"><button type="button" class="ar" data-d="-1" aria-label="Previous stop">&lsaquo;</button><div class="nums-r">'+dn+'</div><button type="button" class="ar" data-d="1" aria-label="Next stop">&rsaquo;</button></nav></div><main class="story"><header class="intro"><p class="date">Tuesday, October 13 · 9:30 to 14:30</p><h1>Your day<br>in Tokyo</h1><p class="who">Patrick, with Yuuki. Kanda and Ikebukuro: bows, anime, ramen, metal records.</p><dl class="cn"><div><dt>Meet</dt><dd class="n">9:30</dd><dd class="s">Hotel lobby</dd></div><div><dt>Finish</dt><dd class="n">14:30</dd><dd class="s">Ikebukuro</dd></div></dl><div class="tools"><a class="tool" href="patrick-ikebukuro-oct13.pdf" download>Save as PDF</a></div></header>'
js='<script>const DAYS=%s,P=%s,GEO=[[35.6985,139.7585,"Kanda"],[35.7345,139.7158,"Ikebukuro"]];'%(json.dumps(['The whole day']+[p[5] for p in P[1:]]),json.dumps([None]+[[p[0],p[1],p[2],p[3],p[4],0] for p in P[1:]]))
js+=open('map.js').read()+'</script></body></html>'
open('index.html','w').write(head+intro+''.join(S)+night+credit+'</main></div>'+js)
